            byte[] tmp = new byte[b.readableBytes()];
            b.readBytes(tmp);
            b.release();
        }
        verifyAndCloseDecoder(decoder, ctx, data);
    } finally {
        for (ByteBuf b : retained) {
            release(b);
        }
    }
}

